/// <summary>
/// PricingAttribute of table <c>SalesTable</c> field SalesStatus
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesTable, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeSalesTableSalesStatus extends UPSPricingAttributeSalesTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(SalesTable, SalesStatus);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    SalesTable salesTable;
    while select SalesStatus from salesTable
        group by SalesStatus
    {
        ret.add(salesTable.SalesStatus);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(SalesTable, SalesStatus));
    qbr.value(queryValue(_value));
}
